package com.alpharip.staffmod.BuildTimelapse.core;
import com.alpharip.staffmod.BuildTimelapse.timeline.*;import java.io.*;import java.util.*;
/** Local-only project metadata, timeline markers and clip-track persistence. */
public final class FileProjectStore implements ProjectStore {
 private final File root;public FileProjectStore(File r){if(r==null)throw new IllegalArgumentException("root");root=r;}
 public void save(BuildTimelapseProject p,Timeline t)throws IOException{if(p==null||t==null)throw new IllegalArgumentException("project/timeline");if(!root.exists()&&!root.mkdirs())throw new IOException("Cannot create project directory");Properties v=new Properties();v.setProperty("format","2");v.setProperty("id",p.getId());v.setProperty("name",p.getName());v.setProperty("world",p.getWorld());v.setProperty("created",Long.toString(p.getCreated()));v.setProperty("notes",p.getNotes());
  v.setProperty("marker.count",Integer.toString(t.getMarkers().size()));int n=0;for(TimelineMarker m:t.getMarkers()){String k="marker."+(n++)+".";v.setProperty(k+"time",Long.toString(m.getTimeMillis()));v.setProperty(k+"label",m.getLabel());v.setProperty(k+"kind",m.getKind().name());}
  v.setProperty("track.count",Integer.toString(t.getTracks().size()));int ti=0;for(TimelineTrack track:t.getTracks()){String tk="track."+ti+".";v.setProperty(tk+"id",track.getId());v.setProperty(tk+"name",track.getName());v.setProperty(tk+"clip.count",Integer.toString(track.getClips().size()));int ci=0;for(TimelineClip clip:track.getClips()){String ck=tk+"clip."+ci+++".";v.setProperty(ck+"id",clip.getId());v.setProperty(ck+"source",clip.getSource());v.setProperty(ck+"start",Long.toString(clip.getStart()));v.setProperty(ck+"duration",Long.toString(clip.getDuration()));v.setProperty(ck+"speed",Double.toString(clip.getSpeed()));}ti++;}
  File tmp=new File(root,p.getId()+".tmp"),dst=new File(root,p.getId()+".btproj");try(OutputStream o=new BufferedOutputStream(new FileOutputStream(tmp))){v.store(o,"Build Timelapse project");}if(dst.exists()&&!dst.delete())throw new IOException("Cannot replace project");if(!tmp.renameTo(dst))throw new IOException("Rename failed");
 }
 private Properties read(String id)throws IOException{if(id==null||id.contains("/")||id.contains("\\")||id.contains(".."))throw new IOException("Invalid project id");File f=new File(root,id+".btproj");if(!f.isFile())throw new FileNotFoundException(f.toString());Properties v=new Properties();try(InputStream in=new BufferedInputStream(new FileInputStream(f))){v.load(in);}String format=v.getProperty("format");if(!"1".equals(format)&&!"2".equals(format))throw new IOException("Unsupported project format");return v;}
 public BuildTimelapseProject load(String id)throws IOException{Properties v=read(id);BuildTimelapseProject p=new BuildTimelapseProject(v.getProperty("id"),v.getProperty("name"),v.getProperty("world"),Long.parseLong(v.getProperty("created")));p.setNotes(v.getProperty("notes",""));return p;}
 public Timeline loadTimeline(String id)throws IOException{Properties v=read(id);Timeline t=new Timeline();int markers=Integer.parseInt(v.getProperty("marker.count","0"));for(int n=0;n<markers;n++){String k="marker."+n+".";t.addMarker(new TimelineMarker(Long.parseLong(v.getProperty(k+"time")),v.getProperty(k+"label"),TimelineMarkerKind.valueOf(v.getProperty(k+"kind"))));}
  int tracks=Integer.parseInt(v.getProperty("track.count","0"));for(int i=0;i<tracks;i++){String k="track."+i+".";TimelineTrack track=new TimelineTrack(v.getProperty(k+"id"),v.getProperty(k+"name"));int clips=Integer.parseInt(v.getProperty(k+"clip.count","0"));for(int j=0;j<clips;j++){String c=k+"clip."+j+".";TimelineClip clip=new TimelineClip(v.getProperty(c+"id"),v.getProperty(c+"source"),Long.parseLong(v.getProperty(c+"start")),Long.parseLong(v.getProperty(c+"duration")));clip.setSpeed(Double.parseDouble(v.getProperty(c+"speed","1")));track.add(clip);}t.addTrack(track);}return t;
 }
}

